Lemma vis_facts Mq mdq LKq Awq crq kq a : inv Mq mdq LKq Awq crq kq a ->
  let H := ahid Awq mdq in let MV := mrestrict H Mq in let ov := PMSPA.o_v AD fb in let osk := PESK.o_sink EE fb in
